#!/usr/bin/env bash
# Download the compiler Halo builds with into toolchain/ (about 170 MB, once):
#   toolchain/llvm-mingw  LLVM-MinGW (clang++, libc++, mingw-w64 headers), from github.com/mstorsjo/llvm-mingw
#   toolchain/winrt       C++/WinRT headers, generated by Microsoft's cppwinrt from this PC's Windows metadata
# tools/build.sh runs this by itself when it finds no compiler. Usage: tools/setup-toolchain.sh
set -euo pipefail
cd "$(dirname "$0")/.."
LLVM_MINGW=20250709
CPPWINRT=2.0.240405.15
dest=toolchain
tmp="$dest/.download"
rm -rf "$tmp"
mkdir -p "$tmp"

unpack() {  # zip -> dir; Windows' own tar.exe reads zip when Git Bash has no unzip
  if command -v unzip >/dev/null; then unzip -q -o "$1" -d "$2"; else mkdir -p "$2"; /c/Windows/System32/tar.exe -xf "$1" -C "$2"; fi
}

if [ ! -x "$dest/llvm-mingw/bin/clang++.exe" ]; then
  echo "== llvm-mingw $LLVM_MINGW"
  curl -fL --progress-bar -o "$tmp/llvm.zip" \
    "https://github.com/mstorsjo/llvm-mingw/releases/download/$LLVM_MINGW/llvm-mingw-$LLVM_MINGW-ucrt-x86_64.zip"
  unpack "$tmp/llvm.zip" "$tmp/llvm"
  rm -rf "$dest/llvm-mingw"
  mv "$tmp/llvm/llvm-mingw-$LLVM_MINGW-ucrt-x86_64" "$dest/llvm-mingw"
fi

if [ ! -f "$dest/winrt/winrt/base.h" ]; then
  echo "== C++/WinRT $CPPWINRT headers"
  curl -fsSL -o "$tmp/cppwinrt.zip" "https://www.nuget.org/api/v2/package/Microsoft.Windows.CppWinRT/$CPPWINRT"
  unpack "$tmp/cppwinrt.zip" "$tmp/cppwinrt"
  rm -rf "$dest/winrt"
  "$tmp/cppwinrt/bin/cppwinrt.exe" -in local -out "$dest/winrt"
fi

rm -rf "$tmp"
echo "toolchain ready in $dest/"
